package storage

import (
	"database/sql"
	"fmt"
	"math"
	"sort"
	"strings"
	"time"

	"github.com/davijardimn/varnqor/internal/domain"
)

const v1DataVersion = "1"

func (s *Store) PrepareV1() error {
	if s == nil || s.db == nil { return nil }
	var version string
	err := s.db.QueryRow(`SELECT value FROM metadata WHERE key='v1_data_version'`).Scan(&version)
	if err != nil && err != sql.ErrNoRows { return err }
	if version == v1DataVersion { return nil }
	tx,err:=s.db.Begin();if err!=nil{return err};defer tx.Rollback()
	if _,err:=tx.Exec(`DELETE FROM usage_calls WHERE total_tokens <= 0`);err!=nil{return fmt.Errorf("clean zero-token usage: %w",err)}
	if _,err:=tx.Exec(`UPDATE usage_calls SET model='' WHERE model LIKE '<%>'`);err!=nil{return fmt.Errorf("clean internal model labels: %w",err)}
	if _,err:=tx.Exec(`INSERT INTO metadata(key,value) VALUES('v1_data_version',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value`,v1DataVersion);err!=nil{return err}
	return tx.Commit()
}

func (s *Store) ResetSource(provider,path string) error {tx,err:=s.db.Begin();if err!=nil{return err};defer tx.Rollback();if _,err:=tx.Exec(`DELETE FROM usage_calls WHERE provider=? AND source_path=?`,provider,path);err!=nil{return err};if _,err:=tx.Exec(`DELETE FROM tool_calls WHERE provider=? AND source_path=?`,provider,path);err!=nil&&!strings.Contains(strings.ToLower(err.Error()),"no such table"){return err};if _,err:=tx.Exec(`DELETE FROM source_files WHERE provider=? AND path=?`,provider,path);err!=nil{return err};return tx.Commit()}
func (s *Store) SourceSummaryAll()(int,int,error){var files,warnings int;err:=s.db.QueryRow(`SELECT COUNT(*),COALESCE(SUM(parse_warnings),0) FROM source_files`).Scan(&files,&warnings);return files,warnings,err}

func (s *Store) DailyUsageAll(now time.Time)(domain.UsageOverview,[]domain.HourUsage,error){location:=now.Location();localNow:=now.In(location);start:=time.Date(localNow.Year(),localNow.Month(),localNow.Day(),0,0,0,0,location);end:=start.AddDate(0,0,1);from,to:=start.UnixMilli(),end.UnixMilli();overview:=domain.UsageOverview{Date:start.Format("2006-01-02")};var firstMS,lastMS sql.NullInt64;err:=s.db.QueryRow(`SELECT COUNT(*),COUNT(DISTINCT provider||char(31)||project),COUNT(DISTINCT provider||char(31)||project||char(31)||session),COALESCE(SUM(input_tokens),0),COALESCE(SUM(output_tokens),0),COALESCE(SUM(cache_creation_tokens),0),COALESCE(SUM(cache_read_tokens),0),COALESCE(SUM(cache_creation_5m_tokens),0),COALESCE(SUM(cache_creation_1h_tokens),0),COALESCE(SUM(total_tokens),0),MIN(timestamp_ms),MAX(timestamp_ms) FROM usage_calls WHERE timestamp_ms>=? AND timestamp_ms<? AND total_tokens>0`,from,to).Scan(&overview.Calls,&overview.Projects,&overview.Sessions,&overview.Tokens.Input,&overview.Tokens.Output,&overview.Tokens.CacheCreation,&overview.Tokens.CacheRead,&overview.Tokens.CacheCreation5m,&overview.Tokens.CacheCreation1h,&overview.Tokens.Total,&firstMS,&lastMS);if err!=nil{return overview,nil,err};if firstMS.Valid{overview.FirstActivity=time.UnixMilli(firstMS.Int64)};if lastMS.Valid{overview.LastActivity=time.UnixMilli(lastMS.Int64)};prompt:=overview.Tokens.Input+overview.Tokens.CacheCreation+overview.Tokens.CacheRead;if prompt>0{overview.CacheReadShare=float64(overview.Tokens.CacheRead)/float64(prompt)*100};models,err:=s.modelUsageAll(from,to);if err!=nil{return overview,nil,err};overview.Models=models;hourly,err:=s.hourlyUsageAll(start,end);return overview,hourly,err}

func (s *Store) UsageWindowAll(start,end time.Time)(domain.TokenTotals,int,error){var tokens domain.TokenTotals;var calls int;err:=s.db.QueryRow(`SELECT COUNT(*),COALESCE(SUM(input_tokens),0),COALESCE(SUM(output_tokens),0),COALESCE(SUM(cache_creation_tokens),0),COALESCE(SUM(cache_read_tokens),0),COALESCE(SUM(cache_creation_5m_tokens),0),COALESCE(SUM(cache_creation_1h_tokens),0),COALESCE(SUM(total_tokens),0) FROM usage_calls WHERE timestamp_ms>=? AND timestamp_ms<? AND total_tokens>0`,start.UnixMilli(),end.UnixMilli()).Scan(&calls,&tokens.Input,&tokens.Output,&tokens.CacheCreation,&tokens.CacheRead,&tokens.CacheCreation5m,&tokens.CacheCreation1h,&tokens.Total);return tokens,calls,err}

func (s *Store) modelUsageAll(from,to int64)([]domain.ModelUsage,error){rows,err:=s.db.Query(`SELECT provider,model,COUNT(*),COALESCE(SUM(input_tokens),0),COALESCE(SUM(output_tokens),0),COALESCE(SUM(cache_creation_tokens),0),COALESCE(SUM(cache_read_tokens),0),COALESCE(SUM(cache_creation_5m_tokens),0),COALESCE(SUM(cache_creation_1h_tokens),0),COALESCE(SUM(total_tokens),0) FROM usage_calls WHERE timestamp_ms>=? AND timestamp_ms<? AND total_tokens>0 GROUP BY provider,model ORDER BY SUM(total_tokens) DESC`,from,to);if err!=nil{return nil,err};defer rows.Close();items:=make([]domain.ModelUsage,0);for rows.Next(){var item domain.ModelUsage;if err:=rows.Scan(&item.Provider,&item.Model,&item.Calls,&item.Tokens.Input,&item.Tokens.Output,&item.Tokens.CacheCreation,&item.Tokens.CacheRead,&item.Tokens.CacheCreation5m,&item.Tokens.CacheCreation1h,&item.Tokens.Total);err!=nil{return nil,err};item.Model=displayModel(item.Provider,item.Model);items=append(items,item)};return items,rows.Err()}
func (s *Store) hourlyUsageAll(start,end time.Time)([]domain.HourUsage,error){buckets:=map[int64]*domain.HourUsage{};for cursor:=start;cursor.Before(end);cursor=cursor.Add(time.Hour){b:=time.Date(cursor.Year(),cursor.Month(),cursor.Day(),cursor.Hour(),0,0,0,start.Location());buckets[b.UnixMilli()]=&domain.HourUsage{Start:b}};rows,err:=s.db.Query(`SELECT timestamp_ms,input_tokens,output_tokens,cache_creation_tokens,cache_read_tokens,cache_creation_5m_tokens,cache_creation_1h_tokens,total_tokens FROM usage_calls WHERE timestamp_ms>=? AND timestamp_ms<? AND total_tokens>0`,start.UnixMilli(),end.UnixMilli());if err!=nil{return nil,err};defer rows.Close();for rows.Next(){var ms int64;var t domain.TokenTotals;if err:=rows.Scan(&ms,&t.Input,&t.Output,&t.CacheCreation,&t.CacheRead,&t.CacheCreation5m,&t.CacheCreation1h,&t.Total);err!=nil{return nil,err};local:=time.UnixMilli(ms).In(start.Location());b:=time.Date(local.Year(),local.Month(),local.Day(),local.Hour(),0,0,0,start.Location());bucket:=buckets[b.UnixMilli()];if bucket==nil{bucket=&domain.HourUsage{Start:b};buckets[b.UnixMilli()]=bucket};bucket.Calls++;domain.AddTokens(&bucket.Tokens,t)};items:=make([]domain.HourUsage,0,len(buckets));for _,b:=range buckets{items=append(items,*b)};sort.Slice(items,func(i,j int)bool{return items[i].Start.Before(items[j].Start)});return items,rows.Err()}

func (s *Store) AttributionAll(start,end time.Time,limit int)(domain.AttributionReport,error){if limit<=0{limit=5};tokens,calls,err:=s.UsageWindowAll(start,end);if err!=nil{return domain.AttributionReport{},err};report:=domain.AttributionReport{Start:start,End:end,Calls:calls,Tokens:tokens};from,to:=start.UnixMilli(),end.UnixMilli();report.Projects,err=s.aggregateAttribution(`SELECT provider,project,COUNT(*),COALESCE(SUM(input_tokens),0),COALESCE(SUM(output_tokens),0),COALESCE(SUM(cache_creation_tokens),0),COALESCE(SUM(cache_read_tokens),0),COALESCE(SUM(cache_creation_5m_tokens),0),COALESCE(SUM(cache_creation_1h_tokens),0),COALESCE(SUM(total_tokens),0) FROM usage_calls WHERE timestamp_ms>=? AND timestamp_ms<? AND total_tokens>0 GROUP BY provider,project ORDER BY SUM(total_tokens) DESC LIMIT ?`,from,to,limit,tokens.Total,"project");if err!=nil{return report,err};report.Models,err=s.aggregateAttribution(`SELECT provider,model,COUNT(*),COALESCE(SUM(input_tokens),0),COALESCE(SUM(output_tokens),0),COALESCE(SUM(cache_creation_tokens),0),COALESCE(SUM(cache_read_tokens),0),COALESCE(SUM(cache_creation_5m_tokens),0),COALESCE(SUM(cache_creation_1h_tokens),0),COALESCE(SUM(total_tokens),0) FROM usage_calls WHERE timestamp_ms>=? AND timestamp_ms<? AND total_tokens>0 GROUP BY provider,model ORDER BY SUM(total_tokens) DESC LIMIT ?`,from,to,limit,tokens.Total,"model");if err!=nil{return report,err};rows,err:=s.db.Query(`SELECT provider,project,session,COUNT(*),COALESCE(SUM(input_tokens),0),COALESCE(SUM(output_tokens),0),COALESCE(SUM(cache_creation_tokens),0),COALESCE(SUM(cache_read_tokens),0),COALESCE(SUM(cache_creation_5m_tokens),0),COALESCE(SUM(cache_creation_1h_tokens),0),COALESCE(SUM(total_tokens),0) FROM usage_calls WHERE timestamp_ms>=? AND timestamp_ms<? AND total_tokens>0 GROUP BY provider,project,session ORDER BY SUM(total_tokens) DESC LIMIT ?`,from,to,limit);if err!=nil{return report,err};defer rows.Close();for rows.Next(){var it domain.AttributionItem;if err:=rows.Scan(&it.Provider,&it.Project,&it.Session,&it.Calls,&it.Tokens.Input,&it.Tokens.Output,&it.Tokens.CacheCreation,&it.Tokens.CacheRead,&it.Tokens.CacheCreation5m,&it.Tokens.CacheCreation1h,&it.Tokens.Total);err!=nil{return report,err};it.Key=it.Provider+":"+it.Project+":"+it.Session;it.Label=it.Session;it.SharePercent=globalShare(it.Tokens.Total,tokens.Total);report.Sessions=append(report.Sessions,it)};return report,nil}
func(s *Store)aggregateAttribution(query string,from,to int64,limit int,total int64,kind string)([]domain.AttributionItem,error){rows,err:=s.db.Query(query,from,to,limit);if err!=nil{return nil,err};defer rows.Close();items:=[]domain.AttributionItem{};for rows.Next(){var it domain.AttributionItem;var raw string;if err:=rows.Scan(&it.Provider,&raw,&it.Calls,&it.Tokens.Input,&it.Tokens.Output,&it.Tokens.CacheCreation,&it.Tokens.CacheRead,&it.Tokens.CacheCreation5m,&it.Tokens.CacheCreation1h,&it.Tokens.Total);err!=nil{return nil,err};it.Key=it.Provider+":"+raw;if kind=="model"{it.Label=displayModel(it.Provider,raw)}else{it.Label=displayProject(raw);it.Project=it.Label};it.SharePercent=globalShare(it.Tokens.Total,total);items=append(items,it)};return items,rows.Err()}

func (s *Store) ProviderTodaySummary(provider string,now time.Time)(int,int64,int,int,time.Time,error){local:=now.In(now.Location());start:=time.Date(local.Year(),local.Month(),local.Day(),0,0,0,0,local.Location());end:=start.AddDate(0,0,1);var calls,files,warnings int;var tokens int64;var lastMS sql.NullInt64;if err:=s.db.QueryRow(`SELECT COUNT(*),COALESCE(SUM(total_tokens),0),MAX(timestamp_ms) FROM usage_calls WHERE provider=? AND timestamp_ms>=? AND timestamp_ms<? AND total_tokens>0`,provider,start.UnixMilli(),end.UnixMilli()).Scan(&calls,&tokens,&lastMS);err!=nil{return 0,0,0,0,time.Time{},err};if err:=s.db.QueryRow(`SELECT COUNT(*),COALESCE(SUM(parse_warnings),0) FROM source_files WHERE provider=?`,provider).Scan(&files,&warnings);err!=nil{return 0,0,0,0,time.Time{},err};last:=time.Time{};if lastMS.Valid{last=time.UnixMilli(lastMS.Int64)};return calls,tokens,files,warnings,last,nil}
func displayModel(provider,value string)string{value=strings.TrimSpace(value);if value!=""&&!strings.HasPrefix(value,"<"){return value};switch provider{case"claude":return"Claude (unspecified)";case"codex":return"Codex (unspecified)";case"gemini":return"Gemini (unspecified)";default:return"Unspecified model"}}
func displayProject(value string)string{value=strings.TrimSpace(value);if value==""||value=="unknown"{return"Unassigned"};return value}
func globalShare(value,total int64)float64{if value<=0||total<=0{return 0};return math.Round(float64(value)/float64(total)*1000)/10}
